import React, { useState, useEffect } from 'react';
import { Search, Phone, Clock, Globe } from 'lucide-react';
import { Link } from 'react-router-dom';

function Nav() {
  const [currentTime, setCurrentTime] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  return (
    <div style={styles.container}>
      <header style={styles.navHeader}>
        <div style={styles.navContainer}>
          
          {/* Top Bar */}
          <div style={styles.navTopBar}>
            <div style={styles.navTopLeft}>
              <div style={styles.navTopItem}>
                <Clock size={16} />
                <span>
                  {currentTime.toLocaleTimeString('en-US', { timeZone: 'Asia/Colombo' })} LKT
                </span>
              </div>
              <div style={styles.navTopItem}>
                <Phone size={16} />
                <span>034-2266789</span>
              </div>
            </div>
            <div style={styles.navTopRight}>
              <button style={styles.navLangBtn}>
                <Globe size={16} />
                <span>English</span>
              </button>
              <button style={styles.navGovBtn}>
                Gov.lk
              </button>
            </div>
          </div>

          {/* Main Header */}
          <div style={styles.navMainHeader}>
            <div style={styles.navLogoSection}>
              <div style={styles.navEmblem}>
                <div style={styles.emblemText}>HC</div>
              </div>
              <div style={styles.navTitle}>
                <h1 style={styles.titleText}>හොරණ නගර සභාව</h1>
                <p style={styles.subtitleText}>HORANA URBAN COUNCIL</p>
              </div>
            </div>

            <div style={styles.navSearchSection}>
              <div style={styles.navSearchContainer}>
                <Search size={18} style={styles.navSearchIcon} />
                <input
                  type="text"
                  placeholder="Search services..."
                  style={styles.navSearchInput}
                />
              </div>
              <button style={styles.navLangSwitch}>
                සිංහල
              </button>
            </div>
          </div>

          {/* Navigation */}
          <nav style={styles.navNavigation}>
            <div style={styles.navMenu}>
              {/* Home */}
              <Link
                to="/mainhome"
                style={styles.navMenuItem}
              >
                <span>🏠</span>
                <span>HOME</span>
              </Link>

              {/* Services Dropdown */}
              <div style={styles.navDropdown}>
                <button style={styles.navDropdownBtn}>
                  <span>⚙️</span>
                  <span>SERVICES</span>
                </button>
                <div style={styles.navDropdownMenu}>
                  <Link
                    to="/adduser?type=playground"
                    style={styles.navDropdownItem}
                  >
                    🏟 Playground Booking
                  </Link>
                  <Link
                    to="/adduser?type=swimming"
                    style={styles.navDropdownItem}
                  >
                    🏊 Swimming Pool Booking
                  </Link>
                  <Link
                    to="/crematorium?type=crematorium"
                    style={styles.navDropdownItem}
                  >
                    ⚰ Crematorium Booking
                  </Link>
                </div>
              </div>

              {/* Bookings */}
              <Link
                to="/userdetails"
                style={styles.navMenuItem}
              >
                <span>📅</span>
                <span>BOOKINGS</span>
              </Link>

              {/* Admin */}
              <Link
                to="/adminhome"
                style={styles.navMenuItem}
              >
